// Saves generated bytes (exports, diagrams) through the shell's save dialog + fs plugin, or a download in the browser.
import { isTauri } from "../ipc/transport";

/** Returns the saved path (Tauri), the file name (browser download), or null when the user cancelled. */
export async function saveBytes(fileName: string, bytes: Uint8Array, filter: { name: string; extension: string; mime: string }): Promise<string | null> {
  if (isTauri) {
    const { save } = await import("@tauri-apps/plugin-dialog");
    const { writeFile } = await import("@tauri-apps/plugin-fs");
    const path = await save({ defaultPath: fileName, filters: [{ name: filter.name, extensions: [filter.extension] }] });
    if (!path) return null;
    await writeFile(path, bytes);
    return path;
  }
  const url = URL.createObjectURL(new Blob([bytes as BlobPart], { type: filter.mime }));
  const a = document.createElement("a");
  a.href = url;
  a.download = fileName;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
  return fileName;
}
